import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import CollectionsContractsActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const CollectionsContractsSchema = {
  entity: 'simukopa_collections_contracts',
  label: 'Overdue by Contract',
  description: '',
  apiBase: apiRoutes.collectionscontracts?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: CollectionsContractsActions,

  groupBy: 'loan',
  groupLabel: 'Contract',
  sortBy: 'late_amount desc',

  fields: [
    { key: 'late', label: 'Overdue Installments', from: 'loan_installments' },
    { key: 'late_amount', label: 'Overdue Amount', from: 'loan_installments.balance_amount', type: 'money' },
    { key: 'penalties', label: 'Penalties', from: 'loan_installments.penalty_amount', type: 'money' },
    { key: 'actions', label: 'Collection Actions', from: 'collection_actions' },
    { key: 'promised', label: 'Promised', from: 'collection_actions.promise_amount', type: 'money' },
    { key: 'share', label: 'Share of Overdue', calc: 'share(late_amount)' },
  ],

  remarks: [
    { if: 'late > 0 && actions == 0', tone: 'bad', title: 'Not followed up', say: '{label} owes {late_amount} overdue and has no collection action in this period.' },
    { if: 'late > 0', tone: 'watch', title: 'Overdue', say: '{label}: {late} overdue installments worth {late_amount}, {actions} follow-ups recorded.' },
    { if: 'true', tone: 'good', title: 'Up to date', say: '{label} has nothing overdue in this period.' },
  ],

  headline: '{label} is the most overdue: {late_amount} across {late} installments.',
};
